while True:
    try:
        self.step()
        self.n_consecutive_format_errors = 0  # reset on any clean step
    except FormatError as e:
        self.cost += e.messages[0].get("extra", {}).get("cost", 0.0)
        self.n_consecutive_format_errors += 1
        if 0 < self.config.max_consecutive_format_errors <= self.n_consecutive_format_errors:
            self.add_messages(*e.messages,
                {"role": "exit", "content": "RepeatedFormatError",
                 "extra": {"exit_status": "RepeatedFormatError", "submission": ""}})
        else:
            self.add_messages(*e.messages)
    except InterruptAgentFlow as e:
        self.add_messages(*e.messages)
    except Exception as e:
        self.handle_uncaught_exception(e)
        raise
    finally:
        self.save(self.config.output_path)
    if self.messages[-1].get("role") == "exit":
        break

observation_template:
  {% if output.exception_info -%}
  <exception>{{output.exception_info}}</exception>
  {% endif -%}
  <returncode>{{output.returncode}}</returncode>
  {% if output.output | length < 10000 -%}
  <output>
  {{ output.output -}}
  </output>
  {%- else -%}
  <warning>
  The output of your last command was too long.
  Please try a different command that produces less output.
  If you're looking at a file you can try use head, tail or sed to view a smaller number of lines selectively.
  ...you can redirect output to a file and then search in that file.
  </warning>
  <output_head> {{ output.output[:5000] }} </output_head>
  <elided_chars> {{ elided_chars }} characters elided </elided_chars>
  <output_tail> {{ output.output[-5000:] }} </output_tail>
  {%- endif -%}
format_error_template:
  {% if finish_reason is defined and (finish_reason == "length" or (finish_reason == "tool_calls" and not has_tool_calls)) -%}
  Your previous response reached the output token limit (finish_reason={{ finish_reason }}) before you produced a tool call, so it was cut off. Respond more concisely and finish with exactly one bash tool call. If you need to think more, do so briefly.
  {%- else -%}
  Tool call error:
  <error>
  {{error}}
  </error>
  Every response needs to use the 'bash' tool at least once to execute commands.
  Call the bash tool with your command as the argument:
  - Tool: bash
  - Arguments: {"command": "your_command_here"}
  If you have completed your assignment, please consult the first message about how to submit your solution (you will not be able to continue working on this task after that).
  {%- endif %}
